package org.brightstats.desktop;
import java.util.*;import javafx.scene.chart.*;import javafx.scene.control.*;import javafx.scene.layout.*;import org.brightstats.stats.BayesianSem;
final class BayesianPlots {
 private BayesianPlots(){}
 static void add(TabPane tabs,BayesianSem.Fit fit){
  ComboBox<String> parameter=new ComboBox<>();fit.model().parameters().forEach(p->parameter.getItems().add(p.name()));parameter.setAccessibleText("Posterior trace parameter");NumberAxis x=new NumberAxis(),y=new NumberAxis();x.setForceZeroInRange(false);y.setForceZeroInRange(false);x.setLabel("Retained unthinned draw index");y.setLabel("Parameter in original units");LineChart<Number,Number> trace=new LineChart<>(x,y);trace.setLegendSide(javafx.geometry.Side.RIGHT);trace.setAnimated(false);trace.setCreateSymbols(false);trace.setPrefHeight(430);List<double[][]> draws=fit.chains().stream().map(BayesianSem.Chain::draws).toList();Runnable refresh=()->{int column=parameter.getSelectionModel().getSelectedIndex();if(column<0)return;trace.getData().clear();trace.setTitle("Independent-chain traces: "+parameter.getValue());for(int c=0;c<draws.size();c++){var series=new XYChart.Series<Number,Number>();series.setName("Chain "+(c+1));double[][] chain=draws.get(c);int count=Math.min(400,chain.length);for(int i=0;i<count;i++){int index=(int)Math.round(i*(chain.length-1.0)/(count-1));series.getData().add(new XYChart.Data<>(index+1,chain[index][column]));}trace.getData().add(series);}};parameter.valueProperty().addListener((o,a,b)->refresh.run());parameter.getSelectionModel().selectFirst();Label note=new Label("Each trace displays at most 400 evenly spaced retained draws per chain. Diagnostics use every unthinned draw, and complete raw chains remain in the numeric report. Inspect chain mixing alongside rank/folded R-hat, bulk/tail ESS and Monte Carlo error. A visually calm trace does not establish convergence.");note.setWrapText(true);note.setMinHeight(Region.USE_PREF_SIZE);note.setMaxWidth(Double.MAX_VALUE);VBox traces=new VBox(10,note,parameter,trace);traces.setStyle("-fx-padding:12;");VBox.setVgrow(trace,Priority.ALWAYS);Tab tab=new Tab("Posterior traces",traces);tab.setClosable(false);tabs.getTabs().add(tab);
  NumberAxis observed=new NumberAxis(),replicated=new NumberAxis();observed.setForceZeroInRange(false);replicated.setForceZeroInRange(false);observed.setLabel("Observed-data Mahalanobis discrepancy");replicated.setLabel("Replicated-data Mahalanobis discrepancy");ScatterChart<Number,Number> scatter=new ScatterChart<>(observed,replicated);scatter.setAnimated(false);scatter.setTitle("Prior and posterior predictive discrepancies");scatter.setPrefHeight(430);for(var collection:List.of(fit.predictive().prior(),fit.predictive().posterior())){var series=new XYChart.Series<Number,Number>();series.setName(collection.getFirst().source()+" draws");for(var draw:collection){var point=new XYChart.Data<Number,Number>(draw.observedMahalanobis(),draw.replicatedMahalanobis());series.getData().add(point);point.nodeProperty().addListener((o,a,node)->{if(node!=null)Tooltip.install(node,new Tooltip(draw.source()+" replication "+draw.index()+"\nObserved: "+draw.observedMahalanobis()+"\nReplicated: "+draw.replicatedMahalanobis()));});}scatter.getData().add(series);}Label predictiveNote=new Label("Each point uses the same parameter draw for its observed and replicated discrepancy, with the original missing-value mask. Above the conceptual y=x diagonal means the replication has larger discrepancy. These are model checks, not calibrated frequentist P values; also inspect the replicated mean/SD tables.");predictiveNote.setWrapText(true);predictiveNote.setMinHeight(Region.USE_PREF_SIZE);predictiveNote.setMaxWidth(Double.MAX_VALUE);VBox panel=new VBox(10,predictiveNote,scatter);panel.setStyle("-fx-padding:12;");VBox.setVgrow(scatter,Priority.ALWAYS);Tab predictiveTab=new Tab("Predictive checks",panel);predictiveTab.setClosable(false);tabs.getTabs().add(predictiveTab);
 }
}
